import{_ as i}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as o,D as r,o as n,c,I as d,w as h,k as p,a as m,R as u,b,e as g}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const N=JSON.parse('{"title":"Hash 与对象字段","description":"学习 Hash 与对象字段 的命令、可观察结果、容量与并发边界。","frontmatter":{"title":"Hash 与对象字段","date":"2026-10-06T00:00:00.000Z","category":"Java课程","tags":["Java","Redis","数据结构"],"description":"学习 Hash 与对象字段 的命令、可观察结果、容量与并发边界。"},"headers":[],"relativePath":"courses/java/15-Redis/03-Hash与对象字段.md","filePath":"courses/java/15-Redis/03-Hash与对象字段.md","lastUpdated":1791252011000}'),k={name:"courses/java/15-Redis/03-Hash与对象字段.md"},H=p("h1",{id:"hash-与对象字段",tabindex:"-1"},[m("Hash 与对象字段 "),p("a",{class:"header-anchor",href:"#hash-与对象字段","aria-label":'Permalink to "Hash 与对象字段"'},"​")],-1),v=u(`<h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>掌握本篇独立命令的输入、返回与状态变化，按访问形状选择结构，并为键、返回数量和失败重试设置边界。</p><h2 id="核心知识点" tabindex="-1">核心知识点 <a class="header-anchor" href="#核心知识点" aria-label="Permalink to &quot;核心知识点&quot;">​</a></h2><p>本篇采用 Redis 8 稳定主版本的基础命令语义；官方文档核对日期：2026-10-06，不声明未验证的补丁版本。<a href="https://redis.io/docs/latest/develop/data-types/" target="_blank" rel="noreferrer">官方数据类型</a> 是本章事实依据。</p><p>Hash 将一个对象映射为 field-value 字节对，适合局部更新；field 不存在与值为空字符串不同。普通 Hash 没有嵌套对象语义，需要自行定义序列化契约。Redis 8 支持字段过期相关扩展，但本篇只用长期稳定的基础命令，不推断字段跟随任何业务时间自动删除。单字段读写通常 O(1)，多字段写 O(N)。</p><p>实验前提：本机独立 Redis 8 服务在 127.0.0.1:6379 运行；通过终端执行 <code>redis-cli -h 127.0.0.1 -p 6379</code> 后在交互提示符输入下面的命令（不是 PowerShell 命令）。有 ACL 时用 <code>--user lab_user --askpass</code> 输入密码。示例注释记录返回，不需要把输出复制成输入；不同客户端的数组排版可能不同。</p><p>每个 H3 都是独立实验。运行每段前、结束后在数据库 0 执行 <code>DEL lab:{core}:h</code>，只清理这些明确的学习 key，不使用通配符、FLUSHDB 或业务库。初始状态：这些 key 均不存在；每段的写入步骤重新创建所需状态。</p><h2 id="常用用法" tabindex="-1">常用用法 <a class="header-anchor" href="#常用用法" aria-label="Permalink to &quot;常用用法&quot;">​</a></h2><h3 id="hset-写入对象字段并区分新增字段与覆盖字段" tabindex="-1"><code>HSET</code>：写入对象字段并区分新增字段与覆盖字段 <a class="header-anchor" href="#hset-写入对象字段并区分新增字段与覆盖字段" aria-label="Permalink to &quot;\`HSET\`：写入对象字段并区分新增字段与覆盖字段&quot;">​</a></h3><p>用于写入对象字段并区分新增字段与覆盖字段。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>HSET lab:{core}:h name Ann age 20</span></span>
<span class="line"><span>HSET lab:{core}:h age 21</span></span>
<span class="line"><span>HGET lab:{core}:h age</span></span>
<span class="line"><span># 关键变化：h 新增 name、age 两字段；随后 age 从 20 更新为 21，字段数量不变。</span></span>
<span class="line"><span># 输出：整数 2、整数 0、&quot;21&quot;。</span></span></code></pre></div><p>返回新增字段数，不是写入成功次数；推荐 HSET 多字段写法，旧 HMSET 不再是首选。 官方参考：<a href="https://redis.io/docs/latest/commands/hset/" target="_blank" rel="noreferrer">HSET</a>。</p><h3 id="hget-读取明确字段并观察不存在字段的结果" tabindex="-1"><code>HGET</code>：读取明确字段并观察不存在字段的结果 <a class="header-anchor" href="#hget-读取明确字段并观察不存在字段的结果" aria-label="Permalink to &quot;\`HGET\`：读取明确字段并观察不存在字段的结果&quot;">​</a></h3><p>用于读取明确字段并观察不存在字段的结果。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>HSET lab:{core}:h name Ann</span></span>
<span class="line"><span>HGET lab:{core}:h name</span></span>
<span class="line"><span>HGET lab:{core}:h missing</span></span>
<span class="line"><span># 关键变化：h 新增 name=Ann，missing 字段仍不存在。</span></span>
<span class="line"><span># 输出：整数 1、&quot;Ann&quot;、(nil)。</span></span></code></pre></div><p>字段值不是自动反序列化的 Java 属性；修改编码需要兼容策略。 官方参考：<a href="https://redis.io/docs/latest/commands/hget/" target="_blank" rel="noreferrer">HGET</a>。</p><h3 id="hmget-按请求顺序批量读取对象的部分字段" tabindex="-1"><code>HMGET</code>：按请求顺序批量读取对象的部分字段 <a class="header-anchor" href="#hmget-按请求顺序批量读取对象的部分字段" aria-label="Permalink to &quot;\`HMGET\`：按请求顺序批量读取对象的部分字段&quot;">​</a></h3><p>用于按请求顺序批量读取对象的部分字段。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>HSET lab:{core}:h name Ann age 20</span></span>
<span class="line"><span>HMGET lab:{core}:h age name missing</span></span>
<span class="line"><span># 关键变化：h 保存 name=Ann、age=20，读取按 age、name、missing 排列。</span></span>
<span class="line"><span># 输出：整数 2，数组为 &quot;20&quot;、&quot;Ann&quot;、(nil)。</span></span></code></pre></div><p>O(N)，适合明确投影，避免为一个字段拉取整个对象。 官方参考：<a href="https://redis.io/docs/latest/commands/hmget/" target="_blank" rel="noreferrer">HMGET</a>。</p><h3 id="hgetall-读取小对象的全部字段和值" tabindex="-1"><code>HGETALL</code>：读取小对象的全部字段和值 <a class="header-anchor" href="#hgetall-读取小对象的全部字段和值" aria-label="Permalink to &quot;\`HGETALL\`：读取小对象的全部字段和值&quot;">​</a></h3><p>用于读取小对象的全部字段和值。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>HSET lab:{core}:h name Ann age 20</span></span>
<span class="line"><span>HGETALL lab:{core}:h</span></span>
<span class="line"><span># 关键变化：h 保存两字段，读取全部 field/value 对而不改变状态。</span></span>
<span class="line"><span># 输出：整数 2；字段集合为 name=Ann、age=20，顺序不保证。</span></span></code></pre></div><p>O(N)，大 Hash 会阻塞且产生大响应；分页遍历应选 HSCAN。 官方参考：<a href="https://redis.io/docs/latest/commands/hgetall/" target="_blank" rel="noreferrer">HGETALL</a>。</p><h3 id="hscan-用游标遍历大对象的字段和值" tabindex="-1"><code>HSCAN</code>：用游标遍历大对象的字段和值 <a class="header-anchor" href="#hscan-用游标遍历大对象的字段和值" aria-label="Permalink to &quot;\`HSCAN\`：用游标遍历大对象的字段和值&quot;">​</a></h3><p>用于用游标遍历大对象的字段和值。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>HSET lab:{core}:h name Ann age 20</span></span>
<span class="line"><span>HSCAN lab:{core}:h 0 COUNT 1</span></span>
<span class="line"><span># 关键变化：h 保存两字段，游标遍历读取其中一批；内容和下一游标依编码决定。</span></span>
<span class="line"><span># 输出：整数 2；随后是下一游标和若干 field/value 对，具体分页不固定。</span></span></code></pre></div><p>重复提交返回游标直到字符串 &quot;0&quot;；COUNT 是提示而非页大小，可能空页或一次返回全部。全遍历 O(N)，单步平均 O(1)；并发变更不是快照，可能重复，调用方需去重。 官方参考：<a href="https://redis.io/docs/latest/commands/hscan/" target="_blank" rel="noreferrer">HSCAN</a>。</p><h3 id="hdel-删除明确字段并观察对象保留的部分" tabindex="-1"><code>HDEL</code>：删除明确字段并观察对象保留的部分 <a class="header-anchor" href="#hdel-删除明确字段并观察对象保留的部分" aria-label="Permalink to &quot;\`HDEL\`：删除明确字段并观察对象保留的部分&quot;">​</a></h3><p>用于删除明确字段并观察对象保留的部分。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>HSET lab:{core}:h name Ann age 20</span></span>
<span class="line"><span>HDEL lab:{core}:h age</span></span>
<span class="line"><span>HLEN lab:{core}:h</span></span>
<span class="line"><span># 关键变化：h 新增 name、age 后移除 age，只保留 name。</span></span>
<span class="line"><span># 输出：整数 2、整数 1、整数 1。</span></span></code></pre></div><p>删除最后一个字段会删除整个 Hash key；返回实际删除字段数。 官方参考：<a href="https://redis.io/docs/latest/commands/hdel/" target="_blank" rel="noreferrer">HDEL</a>。</p><h3 id="hexists-检查字段存在性而不读取字段值" tabindex="-1"><code>HEXISTS</code>：检查字段存在性而不读取字段值 <a class="header-anchor" href="#hexists-检查字段存在性而不读取字段值" aria-label="Permalink to &quot;\`HEXISTS\`：检查字段存在性而不读取字段值&quot;">​</a></h3><p>用于检查字段存在性而不读取字段值。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>HSET lab:{core}:h name &quot;&quot;</span></span>
<span class="line"><span>HEXISTS lab:{core}:h name</span></span>
<span class="line"><span>HEXISTS lab:{core}:h age</span></span>
<span class="line"><span># 关键变化：h 的 name 存在且为空，age 没有被创建。</span></span>
<span class="line"><span># 输出：整数 1、整数 1、整数 0。</span></span></code></pre></div><p>存在但为空的字段仍返回 1；检查与后续修改的组合不是原子条件更新。 官方参考：<a href="https://redis.io/docs/latest/commands/hexists/" target="_blank" rel="noreferrer">HEXISTS</a>。</p><h3 id="hlen-检查对象字段数以识别不受控扩张" tabindex="-1"><code>HLEN</code>：检查对象字段数以识别不受控扩张 <a class="header-anchor" href="#hlen-检查对象字段数以识别不受控扩张" aria-label="Permalink to &quot;\`HLEN\`：检查对象字段数以识别不受控扩张&quot;">​</a></h3><p>用于检查对象字段数以识别不受控扩张。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>HSET lab:{core}:h name Ann age 20</span></span>
<span class="line"><span>HLEN lab:{core}:h</span></span>
<span class="line"><span># 关键变化：h 新增两个字段，读取字段数量为 2。</span></span>
<span class="line"><span># 输出：整数 2、整数 2。</span></span></code></pre></div><p>O(1)；字段数不能表示内存大小，仍要限制每个字段和整个对象的字节量。 官方参考：<a href="https://redis.io/docs/latest/commands/hlen/" target="_blank" rel="noreferrer">HLEN</a>。</p><h3 id="hincrby-原子增加对象里的整数字段" tabindex="-1"><code>HINCRBY</code>：原子增加对象里的整数字段 <a class="header-anchor" href="#hincrby-原子增加对象里的整数字段" aria-label="Permalink to &quot;\`HINCRBY\`：原子增加对象里的整数字段&quot;">​</a></h3><p>用于原子增加对象里的整数字段。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>HSET lab:{core}:h visits 2</span></span>
<span class="line"><span>HINCRBY lab:{core}:h visits 3</span></span>
<span class="line"><span>HGET lab:{core}:h visits</span></span>
<span class="line"><span># 关键变化：visits 从 2 累加 3 后变为 5。</span></span>
<span class="line"><span># 输出：整数 1、整数 5、&quot;5&quot;。</span></span></code></pre></div><p>缺失字段从 0 开始；有符号 64 位整数且不自动提供库存下限约束。 官方参考：<a href="https://redis.io/docs/latest/commands/hincrby/" target="_blank" rel="noreferrer">HINCRBY</a>。</p><h2 id="易混点" tabindex="-1">易混点 <a class="header-anchor" href="#易混点" aria-label="Permalink to &quot;易混点&quot;">​</a></h2><p>命令返回的整数有的表示数量、有的表示旧值或新值，应按命令解释；nil 与空字符串不同。单命令原子不等于跨命令或跨数据库的业务事务。</p><h2 id="课后小问" tabindex="-1">课后小问 <a class="header-anchor" href="#课后小问" aria-label="Permalink to &quot;课后小问&quot;">​</a></h2><ol><li>本篇怎样验证示例没有依赖上一次实验？</li></ol><p>答案：每个小节先清理明确实验 key，再按本段重建输入，读回结果后清理；连接与认证例按注明的连接前置条件执行。</p><ol start="2"><li>网络超时后能否直接重试写操作？</li></ol><p>答案：不能由超时推断服务端未执行。对计数、入队、事件追加等写操作应设计幂等、重试上限与恢复路径。</p><h2 id="本节小结" tabindex="-1">本节小结 <a class="header-anchor" href="#本节小结" aria-label="Permalink to &quot;本节小结&quot;">​</a></h2><p>按输入与输出验证命令语义，再评估数据量、阻塞时间、精度和失败路径；实验清理只针对明确学习 key。</p><h2 id="快速回顾" tabindex="-1">快速回顾 <a class="header-anchor" href="#快速回顾" aria-label="Permalink to &quot;快速回顾&quot;">​</a></h2><p>能根据本篇 H3 搜索命令、重建初始状态、解释返回值，并说明哪些边界需要客户端或业务协议补齐。</p>`,55);function f(a,_,E,q,T,y){const l=i,t=r("ClientOnly");return n(),c("div",null,[H,d(t,null,{default:h(()=>{var s,e;return[(((s=a.$frontmatter)==null?void 0:s.aside)??!0)&&(((e=a.$frontmatter)==null?void 0:e.showArticleMetadata)??!0)?(n(),b(l,{key:0,article:a.$frontmatter},null,8,["article"])):g("",!0)]}),_:1}),v])}const x=o(k,[["render",f]]);export{N as __pageData,x as default};
